mapper.select:
WITH ap AS ( SELECT a.clinic_id, COUNT(*) AS total, COUNT(*) FILTER (WHERE a.status = '已就诊') AS attended, COUNT(*) FILTER (WHERE a.status = '未到诊') AS no_show, COUNT(*) FILTER (WHERE a.status = '已取消') AS cancelled FROM appointment a WHERE a.appointment_time >= #{from} AND a.appointment_time < (#{to}::date + INTERVAL '1 day')
AND a.clinic_id = #{clinicId}
GROUP BY a.clinic_id ), vs AS ( SELECT v.clinic_id, COUNT(*) AS visits FROM visit v WHERE v.arrival_time >= #{from} AND v.arrival_time < (#{to}::date + INTERVAL '1 day') GROUP BY v.clinic_id ), rev AS ( SELECT COALESCE(v.clinic_id, ov.clinic_id) AS clinic_id, COALESCE(SUM(s.total_due), 0) AS revenue FROM statement s LEFT JOIN visit v ON v.visit_id = s.visit_id LEFT JOIN statement o ON o.statement_id = s.reversal_of_id LEFT JOIN visit ov ON ov.visit_id = o.visit_id WHERE s.status IN ('已出具', '待支付', '已结算') AND s.issue_date >= #{from} AND s.issue_date <= #{to} GROUP BY COALESCE(v.clinic_id, ov.clinic_id) ) SELECT c.clinic_id AS clinic_id, c.clinic_name AS clinic_name, COALESCE(ap.total, 0) AS total, COALESCE(ap.attended, 0) AS attended, COALESCE(ap.no_show, 0) AS no_show, COALESCE(ap.cancelled, 0) AS cancelled, COALESCE(vs.visits, 0) AS visits, COALESCE(rev.revenue, 0) AS revenue FROM clinic c LEFT JOIN ap ON ap.clinic_id = c.clinic_id LEFT JOIN vs ON vs.clinic_id = c.clinic_id LEFT JOIN rev ON rev.clinic_id = c.clinic_id WHERE COALESCE(ap.total, 0) > 0 OR COALESCE(vs.visits, 0) > 0 ORDER BY c.clinic_id

SELECT a.channel AS channel, COUNT(*) AS total, COUNT(*) FILTER (WHERE a.status = '未到诊') AS no_show, COUNT(*) FILTER (WHERE a.status = '已取消') AS cancelled, COUNT(*) FILTER (WHERE a.status = '已就诊') AS attended FROM appointment a WHERE a.appointment_time >= #{from} AND a.appointment_time < (#{to}::date + INTERVAL '1 day')
AND a.clinic_id = #{clinicId}
GROUP BY a.channel ORDER BY a.channel
